// Update folds the ledger's complete runs into their host tables (sorted,
// written only when changed) and then truncates the ledger, all under the
// lock every append also takes, so a concurrent append either lands before
// the read (and is folded) or after the truncation (and is kept). A write
// error stops before the truncation; each written table's fold mark makes
// the retry skip what it already holds.
func Update(root string) (*UpdateResult, error) {
	res := &UpdateResult{Folded: map[string]int{}, Wrote: []string{}, Skipped: []Skipped{}}
	if err := os.MkdirAll(filepath.Join(root, filepath.FromSlash(path.Dir(LedgerPath))), 0o755); err != nil {
		return nil, &Error{What: "ledger", Detail: err.Error()}
	}
	unlock, err := platform.Lock(filepath.Join(root, filepath.FromSlash(LockPath)))
	if err != nil {
		return nil, &Error{What: "ledger", Detail: "lock: " + err.Error()}
	}
	defer unlock()
	data, err := readLedger(root)
	if err != nil {
		return nil, err
	}
	if testUpdateHeld != nil {
		testUpdateHeld()
	}
	if len(data) == 0 {
		return res, nil
	}
	all := parseLedger(data, 0)
	res.Skipped = append(res.Skipped, all.Skipped...)
	var hcs []string
	for _, r := range all.Runs {
		if !slices.Contains(hcs, r.HostClass) {
			hcs = append(hcs, r.HostClass)
		}
	}
	slices.Sort(hcs)
	mark := &FoldMark{Bytes: int64(len(data)), SHA256: digest(data)}
	for _, hc := range hcs {
		t, err := readTable(root, hc)
		if err != nil {
			return nil, err
		}
		runs, _ := pendingFor(t, data, hc)
		for _, r := range runs {
			t.fold(r)
		}
		res.Folded[hc] = len(runs)
		t.LedgerFold = mark
		out, err := renderTable(t)
		if err != nil {
			return nil, &Error{What: "table", Detail: err.Error()}
		}
		changed, err := writeFile(filepath.Join(root, filepath.FromSlash(TablePath(hc))), out)
		if err != nil {
			return nil, &Error{What: "table", Detail: TablePath(hc) + ": " + err.Error()}
		}
		if changed {
			res.Wrote = append(res.Wrote, TablePath(hc))
		}
	}
	res.Truncated = bytes.Count(data, []byte{'\n'})
	if !bytes.HasSuffix(data, []byte{'\n'}) {
		res.Truncated++
	}
	if err := os.Truncate(filepath.Join(root, filepath.FromSlash(LedgerPath)), 0); err != nil {
		return nil, &Error{What: "ledger", Detail: err.Error()}
	}
	return res, nil
}

